"""SMTP-based email service with HTML templates for TalentAI."""

import smtplib
import ssl
from html import escape
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText

from app.core.config import settings


class EmailService:
    # ============================================================
    #  🔽  REPLACE THIS WITH YOUR OWN LOGO SOURCE  🔽
    #  (data URI like "data:image/png;base64,..." or URL)
    # ============================================================
    LOGO_SRC = "data:image/png;base64,"
    # ============================================================

    def _build_message(self, to_email: str, subject: str, html_body: str) -> MIMEMultipart:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = subject
        msg["From"] = f"{settings.SMTP_FROM_NAME} <{settings.SMTP_FROM_EMAIL}>"
        msg["To"] = to_email
        msg.attach(MIMEText(html_body, "html"))
        return msg

    def _send(self, to_email: str, subject: str, html_body: str) -> None:
        msg = self._build_message(to_email, subject, html_body)
        context = ssl.create_default_context()
        try:
            if settings.MAIL_USE_SSL:
                with smtplib.SMTP_SSL(settings.SMTP_HOST, settings.SMTP_PORT, context=context) as server:
                    server.login(settings.SMTP_USERNAME, settings.SMTP_PASSWORD)
                    server.sendmail(settings.SMTP_FROM_EMAIL, to_email, msg.as_string())
            else:
                with smtplib.SMTP(settings.SMTP_HOST, settings.SMTP_PORT) as server:
                    server.ehlo()
                    if settings.MAIL_USE_TLS:
                        server.starttls(context=context)
                        server.ehlo()
                    server.login(settings.SMTP_USERNAME, settings.SMTP_PASSWORD)
                    server.sendmail(settings.SMTP_FROM_EMAIL, to_email, msg.as_string())
        except Exception as exc:
            raise RuntimeError(f"Failed to send email to {to_email}: {exc}") from exc

    # ------------------------------------------------------------------ #
    # Branded shell – includes logo via placeholder
    # ------------------------------------------------------------------ #

    def _branded_shell(self, eyebrow: str, title: str, body_html: str) -> str:
        # Use the class variable LOGO_SRC – you set it above
        logo_src = self.LOGO_SRC

        return f"""
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8"/>
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>{escape(eyebrow)} – TalentAI</title>
</head>
<body style="margin:0;padding:0;background:#f4f6f9;font-family:'Segoe UI',Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6f9;padding:40px 0;">
    <tr><td align="center">
      <table width="560" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);">
        <tr>
          <td style="background:linear-gradient(135deg,#123a63 0%,#32a6ae 100%);padding:32px 40px;">
            <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
              <tr>
                <td style="width:60px;vertical-align:middle;padding-right:16px;">
                  <!-- 👇 The logo source is taken from LOGO_SRC – replace that variable above -->
                  <img src="{logo_src}" alt="" width="555" height="236">
                </td>
                <td style="vertical-align:middle;">
                  <h1 style="margin:0;color:#ffffff;font-size:26px;font-weight:700;">TalentAI</h1>
                  <p style="margin:4px 0 0;color:rgba(255,255,255,0.75);font-size:13px;">by Mazik Global Pakistan</p>
                </td>
              </tr>
            </table>
          </td>
        </tr>
        <tr>
          <td style="padding:40px;">
            <p style="margin:0 0 8px;color:#64748b;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.8px;">{escape(eyebrow)}</p>
            <h2 style="margin:0 0 18px;color:#0f172a;font-size:22px;font-weight:700;">{title}</h2>
            {body_html}
          </td>
        </tr>
        <tr>
          <td style="background:#f8fafc;padding:20px 40px;border-top:1px solid #e2e8f0;">
            <p style="margin:0;color:#94a3b8;font-size:12px;">© 2026 Mazik Global Pakistan – TalentAI. All rights reserved.</p>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>
"""

